=== README.md ===
     1	# docsite-pages
     2	
     3	Page model for the documentation site. `pageSlug(title)` turns a page title into the URL segment; slugs are lowercase, hyphen separated and ASCII, and existing URLs must keep resolving.
     4	
     5	Third-party code lives under `vendor/` as exact copies of upstream releases (see `vendor/README.md`); `vendor/slugify` was bumped to 2.0.0 last week.
     6	
     7	Node 24, `npm test`.
=== src/pages.ts ===
     1	// Page model. Slugs are lowercase, hyphen separated, ASCII; they are part of public URLs.
     2	import { slugify } from "../vendor/slugify/index.ts";
     3	
     4	export interface Page {
     5	  title: string;
     6	  slug: string;
     7	  body: string;
     8	}
     9	
    10	export function pageSlug(title: string): string {
    11	  return slugify(title, "-");
    12	}
    13	
    14	export function makePage(title: string, body: string): Page {
    15	  return { title, slug: pageSlug(title), body };
    16	}
=== test/pages.test.ts ===
     1	import { test } from "node:test";
     2	import assert from "node:assert/strict";
     3	import { makePage, pageSlug } from "../src/pages.ts";
     4	
     5	test("release notes page slug", () => {
     6	  assert.equal(pageSlug("release notes 2026"), "release-notes-2026");
     7	});
     8	
     9	test("makePage carries the slug", () => {
    10	  assert.equal(makePage("getting started", "...").slug, "getting-started");
    11	});
=== vendor/README.md ===
     1	# vendor
     2	
     3	Exact copies of upstream releases, one directory per package, with the upstream CHANGELOG. Update by re-vendoring the next release; never patch a vendored file in place, the next re-vendor would silently drop the patch.
=== vendor/slugify/CHANGELOG.md ===
     1	# slugify changelog
     2	
     3	## 2.0.0
     4	
     5	Breaking:
     6	- `slugify(text, separator)` is now `slugify(text, options)`. Passing a string as the second argument is no longer supported.
     7	- Lowercasing is opt-in: pass `{ lower: true }`. 1.x always lowercased.
     8	- The default separator is `_` (was `-`).
     9	
    10	Added:
    11	- `strict: true` drops every character that is not a letter or a digit instead of turning runs of them into a separator.
    12	
    13	## 1.4.2
    14	
    15	- Combining marks are stripped after NFKD normalisation, so accented letters become their base letter.
=== vendor/slugify/index.ts ===
     1	// slugify 2.0.0 (vendored, unmodified)
     2	
     3	export interface SlugifyOptions {
     4	  separator?: string;
     5	  lower?: boolean;
     6	  strict?: boolean;
     7	}
     8	
     9	const escapeRe = (s: string) => s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    10	
    11	export function slugify(text: string, options: SlugifyOptions = {}): string {
    12	  const separator = options.separator ?? "_";
    13	  let out = text.normalize("NFKD").replace(/[\u0300-\u036f]/g, "");
    14	  if (options.lower) out = out.toLowerCase();
    15	  out = options.strict ? out.replace(/[^A-Za-z0-9]+/g, "") : out.replace(/[^A-Za-z0-9]+/g, separator);
    16	  if (separator) {
    17	    const edge = new RegExp(`^(?:${escapeRe(separator)})+|(?:${escapeRe(separator)})+$`, "g");
    18	    out = out.replace(edge, "");
    19	  }
    20	  return out;
    21	}

